package com.sami.app.uom;
import com.sami.app.common.tenancy.TenantContext; import com.sami.app.organization.service.FoundationAuditService; import com.sami.app.uom.domain.*; import com.sami.app.uom.repository.*; import com.sami.app.uom.service.UomService; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class UomServiceTest { @Mock UnitOfMeasureRepository uoms; @Mock UomConversionRepository conversions; @Mock TenantContext tenants; @Mock FoundationAuditService audit; UomService service; @BeforeEach void setup(){service=new UomService(uoms,conversions,tenants,audit);when(tenants.requireTenantId()).thenReturn(7L);}
 @Test void convertsForwardAndReverseWithoutFloatingPoint(){when(uoms.findByTenantIdAndId(7L,1L)).thenReturn(Optional.of(UnitOfMeasure.builder().status("ACTIVE").build()));when(uoms.findByTenantIdAndId(7L,2L)).thenReturn(Optional.of(UnitOfMeasure.builder().status("ACTIVE").build()));when(conversions.findByTenantIdAndFromUomIdAndToUomId(7L,1L,2L)).thenReturn(Optional.of(UomConversion.builder().fromUomId(1L).toUomId(2L).factor(new BigDecimal("12")).status("ACTIVE").build()));assertEquals(new BigDecimal("24"),service.convert(new BigDecimal("2"),1L,2L).convertedQuantity());when(conversions.findByTenantIdAndFromUomIdAndToUomId(7L,2L,1L)).thenReturn(Optional.empty());assertEquals(new BigDecimal("2"),service.convert(new BigDecimal("24"),2L,1L).convertedQuantity());}
 @Test void rejectsSameUomAndNonPositiveFactor(){assertThrows(RuntimeException.class,()->service.createConversion(new com.sami.app.uom.dto.UomDtos.ConversionRequest(1L,1L,BigDecimal.ONE,"ACTIVE")));}
 @Test void inactiveUomCannotConvert(){when(uoms.findByTenantIdAndId(7L,1L)).thenReturn(Optional.of(UnitOfMeasure.builder().status("INACTIVE").build()));assertThrows(RuntimeException.class,()->service.convert(BigDecimal.ONE,1L,2L));}
}
